`);

const badge = document.createElement('div');
badge.className = 'plugin-badge';
badge.textContent = '统计中…';
document.body.appendChild(badge);

const sync = () => {
    const rows = document.querySelectorAll('[data-chat-index]');
    const last = document.querySelector('[data-chat-index]:last-of-type .message-content-wrapper');
    const chars = last ? (last.innerText || '').replace(/\s+/g, '').length : 0;
    badge.textContent = '可见 ' + rows.length + ' 条 · 本轮 ' + chars + ' 字';
};

// 节流：自己插入节点也会触发 observer，用闸门挡住无限循环
let queued = false;
const schedule = () => {
    if (queued) return;
    queued = true;
    requestAnimationFrame(() => { queued = false; sync(); });
};

const observer = new MutationObserver(schedule);
observer.observe(document.body, { childList: true, subtree: true });
setInterval(schedule, 1500);
sync();
api.log('DOM 增强骨架 已挂载');
